SELECT d.d_date, SUM(COALESCE(cr.cr_net_loss,0)) AS catalog_net_loss, SUM(COALESCE(sr.sr_net_loss,0)) AS store_net_loss, (SUM(COALESCE(cr.cr_net_loss,0)) + SUM(COALESCE(sr.sr_net_loss,0))) AS combined_net_loss, CASE WHEN (SUM(COALESCE(cr.cr_net_loss,0)) + SUM(COALESCE(sr.sr_net_loss,0))) = 0 THEN 0 ELSE (SUM(COALESCE(cr.cr_net_loss,0)) / (SUM(COALESCE(cr.cr_net_loss,0)) + SUM(COALESCE(sr.sr_net_loss,0)))) * 100 END AS catalog_loss_pct, CASE WHEN (SUM(COALESCE(cr.cr_net_loss,0)) + SUM(COALESCE(sr.sr_net_loss,0))) = 0 THEN 0 ELSE (SUM(COALESCE(sr.sr_net_loss,0)) / (SUM(COALESCE(cr.cr_net_loss,0)) + SUM(COALESCE(sr.sr_net_loss,0)))) * 100 END AS store_loss_pct, CASE WHEN (SUM(COALESCE(cr.cr_net_loss,0)) + SUM(COALESCE(sr.sr_net_loss,0))) > 500000 THEN 'Critical' WHEN (SUM(COALESCE(cr.cr_net_loss,0)) + SUM(COALESCE(sr.sr_net_loss,0))) > 200000 THEN 'Warning' ELSE 'Normal' END AS loss_severity, RANK() OVER (ORDER BY (SUM(COALESCE(cr.cr_net_loss,0)) + SUM(COALESCE(sr.sr_net_loss,0))) DESC) AS loss_day_rank, COUNT(DISTINCT cc_open.cc_call_center_sk) AS open_center_count, COUNT(DISTINCT cc_close.cc_call_center_sk) AS closed_center_count FROM date_dim d LEFT JOIN catalog_returns cr ON cr.cr_returned_date_sk = d.d_date_sk LEFT JOIN store_returns sr ON sr.sr_returned_date_sk = d.d_date_sk LEFT JOIN call_center cc_open ON cc_open.cc_open_date_sk = d.d_date_sk LEFT JOIN call_center cc_close ON cc_close.cc_closed_date_sk = d.d_date_sk WHERE d.d_year BETWEEN 2021 AND 2022 GROUP BY d.d_date ORDER BY combined_net_loss DESC LIMIT 10
